package com.hbm.satellite.link;
import com.hbm.multiblock.DummyableBlock;import com.hbm.satellite.SatelliteFrequency;import com.hbm.registry.HbmSounds;import com.mojang.serialization.MapCodec;import net.minecraft.ChatFormatting;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.SoundType;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Source2x7x2 mast, no menu; actualchipfrequencysetting and three bottom sourceProxyCombo hosts. */
public final class SatelliteLinkBlock extends DummyableBlock {
 public SatelliteLinkBlock(){super(Properties.of().strength(5,6).sound(SoundType.STONE).requiresCorrectToolForDrops().noOcclusion());}@Override protected MapCodec<? extends DummyableBlock> codec(){return MapCodec.unit(this);}@Override public int[] dimensions(){return new int[]{6,0,1,0,1,0};}@Override public int offset(){return 0;}
 @Override public void setPlacedBy(Level level,BlockPos pos,BlockState state,LivingEntity placer,ItemStack stack){super.setPlacedBy(level,pos,state,placer,stack);if(!level.isClientSide){var core=findCore(level,pos);if(core==null)return;var direction=facing(level.getBlockState(core));var right=direction.getClockWise();for(var port:new BlockPos[]{core.relative(right),core.relative(right).relative(direction,-1),core.relative(direction,-1)})setPort(level,port,true);}}
 @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return isCore(state)?new SatelliteLinkBlockEntity(pos,state):isPort(state)?new SatelliteLinkPort(pos,state):null;}@Override public <T extends BlockEntity>BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return isCore(state)?createTickerHelper(type,SatelliteLinkContent.ENTITY.get(),SatelliteLinkBlockEntity::tick):null;}
 @Override protected ItemInteractionResult useItemOn(ItemStack stack,BlockState state,Level level,BlockPos pos,Player player,InteractionHand hand,BlockHitResult hit){if(!player.isShiftKeyDown()&&stack.getItem() instanceof SatelliteFrequency){var core=findCore(level,pos);if(core==null||!(level.getBlockEntity(core) instanceof SatelliteLinkBlockEntity link))return ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;if(!level.isClientSide){link.freq=SatelliteFrequency.getFreqS(stack);link.setChanged();player.displayClientMessage(Component.translatable("chat.hbm.satellite_link.frequency",link.freq).withStyle(ChatFormatting.YELLOW),false);level.playSound(null,player.getX(),player.getY(),player.getZ(),HbmSounds.get("item.techBleep"),net.minecraft.sounds.SoundSource.PLAYERS,1F,1F);}return ItemInteractionResult.sidedSuccess(level.isClientSide);}return super.useItemOn(stack,state,level,pos,player,hand,hit);}
 @Override protected InteractionResult useWithoutItem(BlockState state,Level level,BlockPos pos,Player player,BlockHitResult hit){return InteractionResult.PASS;}
}
